effect.shader:
const int N_FLARES = 7;

vec3 corDoDisco(int i) {
    if (i == 0) return vec3(1.0, 0.0, 0.0);
    if (i == 1) return vec3(1.0, 0.5, 0.0);
    if (i == 2) return vec3(1.0, 1.0, 0.0);
    if (i == 3) return vec3(0.0, 1.0, 0.2);
    if (i == 4) return vec3(0.0, 0.7, 1.0);
    if (i == 5) return vec3(0.3, 0.2, 1.0);
    return vec3(0.8, 0.0, 1.0);
}

void main() {
    vec4 orig = texture(inputImg, acScreenNorm);
    vec2 centro = vec2(0.5);
    vec2 dir = source - centro;
    vec3 soma = vec3(0.0);
    for (int i = 0; i < N_FLARES; i++) {
        float t = (float(i) + 1.0) / float(N_FLARES + 1);
        vec2 pos = source - dir * (1.0 + t) * spacing * float(N_FLARES);
        vec2 p = acScreenNorm - pos;
        p.x *= acAspect;
        float d = length(p);
        float disco = smoothstep(size, 0.0, d);
        soma += corDoDisco(i) * disco;
    }
    fragColor = vec4(orig.rgb + soma * intensity, orig.a);
}
